import axios from 'axios';
import MockAdapter from 'axios-mock-adapter';

const mock = new MockAdapter(axios, { delayResponse: 500 });

// Mock Users
const mockUser = {
  _id: "user123",
  username: "Demo User",
  email: "demo@example.com",
  profilePicture: "https://i.pravatar.cc/150?u=a042581f4e29026704d",
  bio: "Demo account for portfolio showcase.",
  isAdmin: false
};

const mockPosts = [
  {
    _id: "post1",
    userId: "user123",
    desc: "We are organizing a local food drive this weekend! Need volunteers.",
    image: "https://images.unsplash.com/photo-1593113565214-8cd1639d6757?auto=format&fit=crop&w=500&q=60",
    likes: ["user2", "user3"],
    comments: [],
    createdAt: new Date().toISOString(),
    isDonation: true,
    itemCategory: "Food",
    location: "Amman, Jordan"
  },
  {
    _id: "post2",
    userId: "user2",
    desc: "Have some medical supplies to donate to anyone in need.",
    image: "https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=500&q=60",
    likes: ["user123"],
    comments: [],
    createdAt: new Date(Date.now() - 86400000).toISOString(),
    isDonation: true,
    itemCategory: "Medical",
    location: "Zarqa, Jordan"
  }
];

// Auth Mocks
mock.onPost(/\/api\/auth\/login/).reply(200, {
  user: mockUser,
  token: "mock-jwt-token",
});
mock.onPost(/\/api\/auth\/register/).reply(200, {
  user: mockUser,
  token: "mock-jwt-token",
});

// User Mocks
mock.onGet(/\/api\/users\/.*/).reply(200, mockUser);
mock.onPut(/\/api\/users\/.*/).reply(200, "Account has been updated");

// Posts Mocks
mock.onGet(/\/Posting\/all-posts/).reply(200, mockPosts);
mock.onGet(/\/Posting\/my-posts/).reply(200, [mockPosts[0]]);
mock.onGet(/\/Posting\/post\/.*/).reply(200, mockPosts[0]);
mock.onPost(/\/Posting\/create-post/).reply(200, mockPosts[0]);
mock.onDelete(/\/Posting\/delete-post\/.*/).reply(200, "Post deleted");

// Messages Mocks
mock.onGet(/\/messages\/contacts/).reply(200, [
  { contactId: "user2", lastMessage: "Are those supplies still available?", unreadCount: 1, contactName: "Ahmed", contactAvatar: "https://i.pravatar.cc/150?u=user2" }
]);
mock.onGet(/\/messages\/unread\/count/).reply(200, { count: 1 });
mock.onGet(/\/messages\/.*/).reply(200, [
  { sender: "user2", content: "Yes, you can come pick them up tomorrow.", createdAt: new Date().toISOString() }
]);
mock.onPost(/\/messages/).reply(200, {
  sender: "user123", content: "Great!", createdAt: new Date().toISOString()
});
mock.onPatch(/\/messages\/read/).reply(200, "Messages marked as read");

// Donations/Claims Mocks
mock.onGet(/\/api\/donations\/claims\/count\/.*/).reply(200, { count: 3 });
mock.onGet(/\/api\/donations\/claims/).reply(200, []);

// Feedback Mocks
mock.onGet(/\/api\/feedback\/.*/).reply(200, []);
mock.onPost(/\/api\/feedback/).reply(200, "Feedback saved");

// Fallback (pass through others or reply 200 to avoid crash)
mock.onAny().reply(200, {});

export default mock;

// Mock window.fetch for checkAuthenticated
const originalFetch = window.fetch;
window.fetch = async (url, options) => {
  if (typeof url === 'string' && url.includes('/authentication/verify')) {
    return { json: async () => true, ok: true };
  }
  return originalFetch(url, options);
};

